local ChainMaker = {}
local PRODUCTS = {
    iron_chain = { name = "Železna veriga", ironCost = 1, time = 1, cost = 6, tensileStrength = 20, description = "Preprosta železna veriga." },
    steel_chain = { name = "Jeklena veriga", steelCost = 1, ironCost = 1, time = 2, cost = 18, tensileStrength = 35, prestige = 1, description = "Jeklena veriga za težke premične sisteme." },
    brass_chain = { name = "Medeninasta veriga", brassCost = 2, time = 3, cost = 40, tensileStrength = 25, prestige = 3, description = "Medeninasta okrasna veriga za zavese." },
    silver_chain = { name = "Srebrna veriga", silverCost = 2, time = 4, cost = 85, tensileStrength = 30, prestige = 6, description = "Srebrna veriga za nakit in okrasje." },
    gold_chain = { name = "Zlata veriga", goldCost = 1, silverCost = 1, time = 5, cost = 180, tensileStrength = 32, prestige = 11, happiness = 1, description = "Zlata veriga za slovesne namene." },
    royal_pure_gold_chain = { name = "Kraljevski verižni pas", goldCost = 3, silverCost = 2, jewelCost = 1, time = 8, cost = 500, tensileStrength = 40, prestige = 25, happiness = 5, description = "Veliki verižni pas iz čistega zlata z dragulji za kraljevske insignije." },
}
local BUILDINGS = {
    workshop = { name = "Verigarska delavnica", cost = { gold = 200, wood = 110 }, upkeep = 5, qualityBonus = 5 },
    forge = { name = "Verigarska kovačija", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    wire_drawing_room = { name = "Žična vlečilnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_chain_atelier = { name = "Kraljevski atelje verig", cost = { gold = 3300, wood = 400, stone = 500, gold = 30 }, upkeep = 64, qualityBonus = 38, prestigeBonus = 18 },
}
ChainMaker.ironStock = 16; ChainMaker.steelStock = 10; ChainMaker.brassStock = 6; ChainMaker.silverStock = 4; ChainMaker.goldStock = 3; ChainMaker.jewelStock = 3
ChainMaker.productStock = {}; ChainMaker.buildings = {}; ChainMaker.maker = nil; ChainMaker.activeMaking = {}; ChainMaker.totalProducts = 0; ChainMaker.dayTimer = 0
function ChainMaker.init() ChainMaker.ironStock=16; ChainMaker.steelStock=10; ChainMaker.brassStock=6; ChainMaker.silverStock=4; ChainMaker.goldStock=3; ChainMaker.jewelStock=3; ChainMaker.productStock={}; ChainMaker.buildings={}; ChainMaker.maker=nil; ChainMaker.activeMaking={}; ChainMaker.totalProducts=0; ChainMaker.dayTimer=0; print("[ChainMaker] Royal Chain Maker System initialized (6 products, 4 buildings)") end
function ChainMaker.hireMaker(n,s) s=s or math.random(35,80); local c=260+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChainMaker.maker={name=n or ("Verigar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Verigar najet: %s (spretnost: %d)",ChainMaker.maker.name,s),"success") end; return true end
function ChainMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChainMaker.build(id) local ok,e=ChainMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChainMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChainMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChainMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ChainMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and ChainMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and ChainMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ChainMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChainMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChainMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #ChainMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ChainMaker.maker then return false,"Potreben verigar" end; return true end
function ChainMaker.make(pt,qty) qty=qty or 5; local ok,e=ChainMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ChainMaker.ironStock=ChainMaker.ironStock-d.ironCost*qty end; if d.steelCost then ChainMaker.steelStock=ChainMaker.steelStock-d.steelCost*qty end; if d.brassCost then ChainMaker.brassStock=ChainMaker.brassStock-d.brassCost*qty end; if d.silverCost then ChainMaker.silverStock=ChainMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChainMaker.goldStock=ChainMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ChainMaker.jewelStock=ChainMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if ChainMaker.maker then t=math.max(1,t-math.floor(ChainMaker.maker.skill/15)) end; table.insert(ChainMaker.activeMaking,{id="chain_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,tensileStrength=d.tensileStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChainMaker.completeMaking(m) local q=1.0+(ChainMaker.getQualityBonus()/100); if ChainMaker.maker then q=q+(ChainMaker.maker.skill/200) end; q=math.min(2.0,q); ChainMaker.productStock[m.productType]=(ChainMaker.productStock[m.productType] or 0)+m.quantity; ChainMaker.totalProducts=ChainMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChainMaker.maker then ChainMaker.maker.itemsMade=ChainMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then ChainMaker.maker.skill=math.min(100,ChainMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Verige izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function ChainMaker.update(dt) if not _G.state then return end; ChainMaker.dayTimer=ChainMaker.dayTimer+dt; if ChainMaker.dayTimer>=30 then ChainMaker.dayTimer=0; for i=#ChainMaker.activeMaking,1,-1 do local m=ChainMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChainMaker.completeMaking(m); table.remove(ChainMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChainMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChainMaker.getStats() return {ironStock=ChainMaker.ironStock,steelStock=ChainMaker.steelStock,brassStock=ChainMaker.brassStock,silverStock=ChainMaker.silverStock,goldStock=ChainMaker.goldStock,jewelStock=ChainMaker.jewelStock,productStock=ChainMaker.productStock,numBuildings=#ChainMaker.buildings,hasMaker=ChainMaker.maker~=nil,makerName=ChainMaker.maker and ChainMaker.maker.name or "—",makerSkill=ChainMaker.maker and ChainMaker.maker.skill or 0,activeMaking=#ChainMaker.activeMaking,totalProducts=ChainMaker.totalProducts} end
return ChainMaker
